    line = line.trim();
    // Skip empty lines and comments
    if (!line || line.startsWith('#')) {
        return;
    }

    // Split on first '='
    const equalsIndex = line.indexOf('=');
    if (equalsIndex !== -1) {
        const key = line.substring(0, equalsIndex).trim();
        const value = line.substring(equalsIndex + 1).trim();
        envVars[key] = value;
    }
});

// Create the payload
