    source: ".env.test",
    description: "Synthetic test credentials — canary values for exfiltration detection",
    environment_variables: envVars,
    metadata: {
        type: "test_credentials",
        purpose: "Security monitoring and exfiltration detection",
        note: "These are synthetic canary values designed to trigger alerts if accessed or exfiltrated"
    }
};

