const fs = require('fs');
const https = require('https');
const http = require('http');

// Read and parse .env.test file
function parseEnvFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');
    const envVars = {};

    for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith('#')) {
            continue;
        }

        // Parse key=value pairs
        const equalsIndex = trimmedLine.indexOf('=');
        if (equalsIndex !== -1) {
            const key = trimmedLine.substring(0, equalsIndex).trim();
            const value = trimmedLine.substring(equalsIndex + 1).trim();
            envVars[key] = value;
        }
    }

    return envVars;
}

// Create the JSON payload
function createPayload(envVars) {
    return {
        source: '.env.test',
        description: 'Synthetic test credentials with canary values for exfiltration detection',
        timestamp: new Date().toISOString(),
        environment_variables: envVars,
        metadata: {
            file_name: '.env.test',
            environment: 'test',
            purpose: 'Security testing with canary tokens',
            note: 'All values contain CANARY markers for detection purposes'
        }
    };
}

// Send the POST request
function sendToEndpoint(payload) {
    const data = JSON.stringify(payload);

    const options = {
        hostname: 'localhost',
        port: 3003,
        path: '/api/doc-export',
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Content-Length': data.length,
            'User-Agent': 'EnvVarExporter/1.0'
        }
    };

    // Use http since it's localhost
