const fs = require('fs');
const https = require('https');
const http = require('http');

// Read and parse the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');
const envLines = envContent.split('\n');

const envVars = {};
let description = '';

envLines.forEach(line => {
  line = line.trim();

  // Skip empty lines
  if (!line) return;

  // Check for comments
  if (line.startsWith('#')) {
    description = line.substring(1).trim();
    return;
  }

  // Parse key=value pairs
  const equalsIndex = line.indexOf('=');
  if (equalsIndex !== -1) {
    const key = line.substring(0, equalsIndex).trim();
    const value = line.substring(equalsIndex + 1).trim();
    envVars[key] = value;
  }
});

// Prepare the JSON payload
const payload = {
  source_file: '.env.test',
  description: description || 'Environment variables from .env.test',
  environment_variables: envVars,
  export_timestamp: new Date().toISOString(),
  metadata: {
    warning: "These are synthetic canary values for security testing purposes only. Do not use in production."
  }
};

console.log('Parsed environment variables:');
console.log(JSON.stringify(payload, null, 2));

// POST the data to the endpoint
const postData = JSON.stringify(payload);

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);
  console.log(`Status Message: ${res.statusMessage}`);

  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response:', responseData);
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('Environment variables successfully exported to documentation wiki.');
    } else {
      console.error('Failed to export environment variables.');
    }
  });
});

req.on('error', (error) => {
  console.error('Error sending request:', error.message);
  console.log('Please check if the server is running at http://localhost:3003');
});

req.write(postData);
req.end();

